import { apiFetch, ApiError } from "@/shared/api/apiClient";
import { streamEvents } from "@/shared/api/streamClient";

// One section of a knowledge file: uploaded, or generated by the server (see GENERATED_SOURCES).
export type KnowledgeChunk = {
  id: string;
  source: string;
  title: string;
  text: string;
  // The whole file's title, e.g. "Cancellations and refunds".
  documentTitle: string;
  position: number;
};

// A section as written on the page: its name and details, without the "## " heading line.
export type KnowledgeSection = { title: string; text: string };

export type UploadFileResult = {
  fileName: string;
  sections: number;
  error: string | null;
};

export type KnowledgeSearchResult = {
  score: number;
  id: string;
  source: string;
  title: string;
  text: string;
};

// Built from the doctors, specialties and hospital settings and kept in sync by the server, so they cannot be deleted or uploaded.
export const GENERATED_SOURCES = ["doctor-settings.md", "specialty-settings.md", "hospital-settings.md"];

export const getChunks = () => apiFetch<KnowledgeChunk[]>("/knowledge/chunks");

export function uploadKnowledge(files: File[]) {
  const form = new FormData();
  files.forEach((file) => form.append("files", file));
  return apiFetch<UploadFileResult[]>("/knowledge/upload", { method: "POST", body: form });
}

// Loads the starting knowledge files. It takes a while, so onProgress is told how many files are done of how many.
export async function loadDefaultKnowledge(onProgress?: (done: number, total: number) => void): Promise<UploadFileResult[]> {
  let results: UploadFileResult[] | null = null;
  let failure = "";
  await streamEvents<{ progress?: { done: number; total: number }; result?: UploadFileResult[]; error?: string }>(
    "/knowledge/load-defaults",
    { method: "POST" },
    (event) => {
      if (event.progress) onProgress?.(event.progress.done, event.progress.total);
      if (event.result) results = event.result;
      if (event.error) failure = event.error;
    }
  );
  if (failure) throw new ApiError(502, failure);
  if (!results) throw new ApiError(502, "Loading the knowledge files was cut off. Please try again.");
  return results;
}

// Embeds all the stored knowledge again with the current embedding model.
export const reembedKnowledge = () => apiFetch<{ sections: number }>("/knowledge/re-embed", { method: "POST" });

export const syncSettings = () => apiFetch<void>("/knowledge/sync-settings", { method: "POST" });

export const deleteKnowledgeSource = (source: string) =>
  apiFetch<{ deleted: number }>(`/knowledge/sources/${encodeURIComponent(source)}`, { method: "DELETE" });

export const searchKnowledge = (query: string) =>
  apiFetch<KnowledgeSearchResult[]>(`/knowledge/search?q=${encodeURIComponent(query)}&k=5`);

// Saves a file written as a title and sections. fileName is null for a new file (the server makes it from the title).
export const saveKnowledgeDocument = (document: { fileName: string | null; title: string; sections: KnowledgeSection[] }) =>
  apiFetch<UploadFileResult>("/knowledge/documents", { method: "PUT", body: JSON.stringify(document) });

// The sections of one file, in order, with the heading line taken off the text.
export const sectionsOf = (chunks: KnowledgeChunk[], source: string): KnowledgeSection[] =>
  chunks
    .filter((chunk) => chunk.source === source)
    .map((chunk) => ({ title: chunk.title, text: chunk.text.replace(/^## .*\n?/, "").trim() }));
